/**
 * @brief Check whether a block ends in an unconditional edge to the given
 * target.
 */
static bool jumps_to(const IrBlock* block, IrBlockId target) {
  return block->terminator.type == IR_TERMINATOR_JUMP &&
         block->terminator.value.jump_target == target;
}

/**
 * @brief Count incoming control-flow edges to a block.
 */
static size_t edge_count(const IrFunction* fn, IrBlockId target) {
  size_t count = fn->entrypoint == target;
  for (IrBlockId b = 0; b < fn->blocks.count; b++) {
    const IrBlock* block = &fn->blocks.data[b];
    const IrBlockTerminator* term = &block->terminator;
    count += jumps_to(block, target);
    if (term->type == IR_TERMINATOR_CONDITIONAL) {
      count += term->value.conditional_target.true_target == target;
      count += term->value.conditional_target.false_target == target;
    }
  }

  return count;
}

/**
 * @brief Expose mutable operands for supported instruction layouts.
 */
static size_t operands_of(IrInstruction* inst, IrOperand** operands) {
  switch (ir_get_instruction_class(inst)) {
    case IR_INST_CLASS_UNARY:
      operands[0] = &inst->operands.unary.operand;
      return 1;
    case IR_INST_CLASS_BINARY:
      operands[0] = &inst->operands.binary.left;
      operands[1] = &inst->operands.binary.right;
      return 2;
    case IR_INST_CLASS_STORE:
      operands[0] = &inst->operands.store.source;
      return 1;
    default:
      return 0;
  }
}

/**
 * @brief Test whether an operand directly references the given value ID.
 */
static bool direct_use(IrOperand operand, IrValueId value) {
  return operand.type == IR_OP_VALUE && operand.value.id == value;
}

/**
 * @brief Count direct references to a value in one instruction.
 */
static unsigned instruction_uses(IrInstruction* inst, IrValueId value) {
  unsigned count = 0;
  if (inst->type == IR_INST_CALL) {
    for (size_t i = 0; i < inst->operands.call.arg_count; i++) {
      count += direct_use(inst->operands.call.args[i], value);
    }
  } else {
    IrOperand* operands[2];
    size_t n = operands_of(inst, operands);
    for (size_t i = 0; i < n; i++) {
      count += direct_use(*operands[i], value);
    }
  }

  return count;
}

/**
 * @brief Evaluate the loop's ordered bound test for a concrete index.
 */
static bool range_test(IrInstructionType type, IrInt current, IrInt end) {
  switch (type) {
    case IR_INST_LT:
      return current < end;
    case IR_INST_LE:
      return current <= end;
    case IR_INST_GT:
      return current > end;
    case IR_INST_GE:
      return current >= end;
    default:
      return false;
  }
}

