/**
 * @brief Return the value operand carried by a terminator, if it has one.
 */
static IrOperand* terminator_operand(IrBlockTerminator* term) {
  switch (term->type) {
    case IR_TERMINATOR_CONDITIONAL:
      return &term->value.conditional_target.condition;
    case IR_TERMINATOR_RETURN:
      return &term->value.return_value;
    case IR_TERMINATOR_EXIT:
      return &term->value.exit_code;
    default:
      return NULL;
  }
}

/**
 * @brief Count uses inside the region before checking for escaping values.
 */
static size_t region_uses(IrFunction* fn,
                          const RangeBody* body,
                          IrValueId value) {
  size_t uses = 0;
  for (size_t b = 0; b < body->count; b++) {
    IrBlock* block = &fn->blocks.data[body->blocks[b]];
    for (size_t i = 0; i < block->instructions.count; i++) {
      uses += instruction_uses(&block->instructions.data[i], value);
    }
    IrOperand* operand = terminator_operand(&block->terminator);
    uses += operand && direct_use(*operand, value);
  }

  return uses;
}

/**
 * @brief Replace split-loop induction operands with the selected iteration
 * value.
 */
static void substitute_iteration(IrFunction* fn,
                                 const RangeBody* body,
                                 IrOperand* operand,
                                 IrValueId induction,
                                 IrStackSlotId slot,
                                 IrOperand current,
                                 size_t offset) {
  if (operand->type != IR_OP_VALUE) {
    return;
  }

  if (operand->value.id == induction) {
    *operand = current;
    return;
  }

  for (size_t b = 0; b < body->count; b++) {
    const IrInstructionArray* instructions =
        &fn->blocks.data[body->blocks[b]].instructions;
    for (size_t i = 0; i < instructions->count; i++) {
      const IrInstruction* definition = &instructions->data[i];
      if (definition->result != operand->value.id) {
        continue;
      }
      if (definition->type == IR_INST_LOAD &&
          definition->operands.load.source == slot) {
        *operand = current;
      } else {
        operand->value.id += offset;
      }
      return;
    }
  }
}

/**
 * @brief Copy one iteration block with fresh results and the substituted
 * induction value.
 */
static void clone_iteration_block(Ctx* ctx,
                                  IrFunctionId fid,
                                  IrBlockId destination,
                                  IrBlockId source,
                                  const RangeBody* body,
                                  IrValueId induction,
                                  IrStackSlotId slot,
                                  IrOperand current,
                                  size_t offset) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  const IrInstructionArray* original = &fn->blocks.data[source].instructions;
  IrInstructionArray* target = &fn->blocks.data[destination].instructions;
  for (size_t i = 0; i < original->count; i++) {
    IrInstruction inst = original->data[i];
    if (inst.type == IR_INST_LOAD && inst.operands.load.source == slot) {
      continue;
    }
    optimizer_clone_instruction(ctx, fid, destination, inst, 0, 0, NULL, 0);
    IrInstruction* copy = &target->data[target->count - 1];
    if (copy->result != IR_INVALID_ID) {
      copy->result += offset;
    }
    IrOperand* operands[2];
    size_t count = operands_of(copy, operands);
    for (size_t a = 0; a < count; a++) {
      substitute_iteration(fn, body, operands[a], induction, slot, current,
                           offset);
    }
    if (copy->type == IR_INST_CALL) {
      for (size_t a = 0; a < copy->operands.call.arg_count; a++) {
        substitute_iteration(fn, body, &copy->operands.call.args[a], induction,
                             slot, current, offset);
      }
    }
  }
}

/**
 * @brief Translate a region edge to the selected copy of its iteration.
 */
static IrBlockId iteration_target(const RangeBody* body,
                                  IrBlockId first,
                                  IrBlockId target) {
  return target == body->latch ? first + body->count
                               : first + region_index(body, target);
}

/**
 * @brief Emit the store that updates the loop's induction slot.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Run two linear range iterations per condition check when the trip
// count is exact.
static void store_induction(Ctx* ctx,
                            IrFunctionId fid,
                            IrBlockId block,
                            IrStackSlotId slot,
                            IrOperand value) {
  ir_add_instruction(
      ctx, fid, block,
      (IrInstruction){.type = IR_INST_STORE,
                      .operands.store = {.source = value, .target = slot}});
}

/**
 * @brief Build a paired counted loop and account for any odd final iteration.
 */
static void unroll_range_by_two(Ctx* ctx,
                                IrFunctionId fid,
                                IrBlockId pre,
                                const RangeBody* body,
                                IrValueId induction,
                                IrStackSlotId slot,
                                IrInt start,
                                IrInt step,
                                uint64_t count,
                                IrValueId next) {
  IrFunction* fn = &ctx->ir.functions.data[fid];
  size_t original_values = fn->value_count;
  if (count % 2 != 0) {
    size_t offset = fn->value_count;
    clone_iteration_block(ctx, fid, pre, body->blocks[0], body, induction, slot,
                          (IrOperand){IR_OP_INT32, {.int32_value = start}},
                          offset);
    fn->value_count = offset + original_values;
    store_induction(ctx, fid, pre, slot,
                    (IrOperand){IR_OP_INT32, {.int32_value = start + step}});
  }

  size_t offset = fn->value_count;
  IrOperand current = {IR_OP_VALUE, {.id = next}};
  clone_iteration_block(ctx, fid, body->latch, body->blocks[0], body, induction,
                        slot, current, offset);
  fn->value_count = offset + original_values;
  IrValueId advanced = ir_add_instruction(
      ctx, fid, body->latch,
      (IrInstruction){.type = IR_INST_ADD,
                      .result_type = IR_INT,
                      .operands.binary = {
                          .left = current,
                          .right = {IR_OP_INT32, {.int32_value = step}},
                      }});
  store_induction(ctx, fid, body->latch, slot,
                  (IrOperand){IR_OP_VALUE, {.id = advanced}});
}

