static bool invariant_operand(IrBlock* const* blocks,
                              size_t count,
                              IrOperand operand) {
  if (operand.type != IR_OP_VALUE) {
    return true;
  }

  for (size_t b = 0; b < count; b++) {
    for (size_t i = 0; i < blocks[b]->instructions.count; i++) {
      if (blocks[b]->instructions.data[i].result == operand.value.id) {
        return false;
      }
    }
  }

  return true;
}

