static bool invariant_load(const IrFunction* fn,
                           const IrBlock* pre,
                           IrBlock* const* blocks,
                           size_t count,
                           IrStackSlotId slot) {
  if (slot >= fn->parameter_count && !stores_slot(pre, slot)) {
    return false;
  }

  for (size_t b = 0; b < count; b++) {
    if (stores_slot(blocks[b], slot)) {
      return false;
    }
  }

  return true;
}

/**
 * @brief Move invariant operations safe to execute before the loop into its
 * preheader.
 */
// Hoist only instructions safe to execute even when the body never runs.
static void hoist_simple_loop(Ctx* ctx,
                              const IrFunction* fn,
                              IrBlock* pre,
                              IrBlock* const* blocks,
                              size_t count) {
  for (size_t b = 0; b < count; b++) {
    IrInstructionArray* from = &blocks[b]->instructions;
    for (size_t i = 0; i < from->count;) {
      IrInstruction inst = from->data[i];
      IrOperand* operands[2];
      size_t operand_count = operands_of(&inst, operands);
      bool safe = inst.type == IR_INST_NOT || inst.type == IR_INST_INT2DOUBLE ||
                  (inst.type >= IR_INST_EQ && inst.type <= IR_INST_GE);
      if (inst.type == IR_INST_LOAD) {
        safe =
            invariant_load(fn, pre, blocks, count, inst.operands.load.source);
      } else if (inst.type == IR_INST_CALL &&
                 inst.operands.call.type == IR_FX_STR_LEN) {
        safe = invariant_operand(blocks, count, inst.operands.call.args[0]);
      }
      for (size_t j = 0; j < operand_count && safe; j++) {
        safe = invariant_operand(blocks, count, *operands[j]);
      }
      if (!safe) {
        i++;
        continue;
      }
      array_append(ctx, &pre->instructions, inst);
      array_remove(ctx, from, i);
    }
  }
}

